**`packages/material-ui/src/useMediaQuery/useMediaQuery.js`** — useMediaQuery(function)

```javascript
1	import React from 'react';
2	import { getThemeProps, useTheme } from '@material-ui/styles';
3	
4	// This variable will be true once the server-side hydration is completed.
5	let hydrationCompleted = false;
6	
7	function useMediaQuery(queryInput, options = {}) {
8	  const theme = useTheme();
9	  const props = getThemeProps({
10	    theme,
11	    name: 'MuiUseMediaQuery',
12	    props: {},
13	  });
14	
15	  if (process.env.NODE_ENV !== 'production') {
16	    if (typeof queryInput === 'function' && theme === null) {
17	      console.error(
18	        [
19	          'Material-UI: the `query` argument provided is invalid.',
20	          'You are providing a function without a theme in the context.',
21	          'One of the parent elements needs to use a ThemeProvider.',
22	        ].join('\n'),
23	      );
24	    }
25	  }
26	
27	  let query = typeof queryInput === 'function' ? queryInput(theme) : queryInput;
28	  query = query.replace(/^@media( ?)/m, '');
29	
30	  // Wait for jsdom to support the match media feature.
31	  // All the browsers Material-UI support have this built-in.
32	  // This defensive check is here for simplicity.
33	  // Most of the time, the match media logic isn't central to people tests.
34	  const supportMatchMedia =
35	    typeof window !== 'undefined' && typeof window.matchMedia !== 'undefined';
36	
37	  const { defaultMatches = false, noSsr = false, ssrMatchMedia = null } = {
38	    ...props,
39	    ...options,
40	  };
41	
42	  const [match, setMatch] = React.useState(() => {
43	    if ((hydrationCompleted || noSsr) && supportMatchMedia) {
44	      return window.matchMedia(query).matches;
45	    }
46	    if (ssrMatchMedia) {
47	      return ssrMatchMedia(query).matches;
48	    }
49	
50	    // Once the component is mounted, we rely on the
51	    // event listeners to return the correct matches value.
52	    return defaultMatches;
53	  });
54	
55	  React.useEffect(() => {
56	    let active = true;
57	    hydrationCompleted = true;
58	
59	    if (!supportMatchMedia) {
60	      return undefined;
61	    }
62	
63	    const queryList = window.matchMedia(query);
64	    const updateMatch = () => {
65	      // Workaround Safari wrong implementation of matchMedia
66	      // TODO can we remove it?
67	      // https://github.com/mui-org/material-ui/pull/17315#issuecomment-528286677
68	      if (active) {
69	        setMatch(queryList.matches);
70	      }
71	    };
72	    updateMatch();
73	    queryList.addListener(updateMatch);
74	    return () => {
75	      active = false;
76	      queryList.removeListener(updateMatch);
77	    };
78	  }, [query, supportMatchMedia]);
79	
80	  return match;
81	}
82	
83	export function testReset() {
84	  hydrationCompleted = false;
85	}
86	
87	export default useMediaQuery;
```

